1	package nexusbench
2	
3	import (
4		"errors"
5		"fmt"
6		"strings"
7		"testing"
8	)
9	
10	// namedKinds is every kind of the D-F table the tests refer to by name.
11	var namedKinds = []struct {
12		name string
13		kind ErrKind
14	}{
15		{"KubectlMissing", KubectlMissing},
16		{"ContextNotFound", ContextNotFound},
17		{"ClusterUnreachable", ClusterUnreachable},
18		{"Forbidden", Forbidden},
19		{"NamespaceForeign", NamespaceForeign},
20		{"NamespaceMissing", NamespaceMissing},
21		{"NodePortTaken", NodePortTaken},
22		{"AdmissionDenied", AdmissionDenied},
23		{"PodPending", PodPending},
24		{"ImagePull", ImagePull},
25		{"Crash", Crash},
26		{"Deadline", Deadline},
27		{"RESTUnreachable", RESTUnreachable},
28		{"ProvisionFailed", ProvisionFailed},
29	}
30	
31	func TestErrKindsAreDistinct(t *testing.T) {
32		seen := map[ErrKind]string{}
33		for _, k := range namedKinds {
34			if other, dup := seen[k.kind]; dup {
35				t.Errorf("%s and %s share the value %d", k.name, other, k.kind)
36			}
37			seen[k.kind] = k.name
38		}
39	}
40	
41	func TestOpsAreDistinct(t *testing.T) {
42		ops := map[string]Op{"OpUp": OpUp, "OpProvision": OpProvision, "OpDown": OpDown, "OpStatus": OpStatus}
43		seen := map[Op]string{}
44		for name, op := range ops {
45			if other, dup := seen[op]; dup {
46				t.Errorf("%s and %s share the value %d", name, other, op)
47			}
48			seen[op] = name
49		}
50	}
51	
52	func TestBenchErrorMessage(t *testing.T) {
53		tests := []struct {
54			name string
55			err  *BenchError
56			want string
57		}{
58			{
59				name: "cause then check",
60				err: &BenchError{
61					Kind:  ContextNotFound,
62					Cause: `no kubeconfig context named "datomir"`,
63					Check: "kubectl config get-contexts",
64				},
65				want: `no kubeconfig context named "datomir". Check: kubectl config get-contexts`,
66			},
67			{
68				name: "the wrapped error is not part of the message",
69				err: &BenchError{
70					Kind:  ClusterUnreachable,
71					Cause: "the cluster does not answer",
72					Check: "kubectl --context datomir get --raw /readyz",
73					Err:   errors.New("exit status 1"),
74				},
75				want: "the cluster does not answer. Check: kubectl --context datomir get --raw /readyz",
76			},
77		}
78		for _, tt := range tests {
79			t.Run(tt.name, func(t *testing.T) {
80				if got := tt.err.Error(); got != tt.want {
81					t.Errorf("Error() = %q, want %q", got, tt.want)
82				}
83			})
84		}
85	}
86	
87	// A sub-process error can carry a secret in its text; Error() is what reaches
88	// the terminal, so it must never print the wrapped error.
89	func TestBenchErrorDoesNotEchoTheWrappedError(t *testing.T) {
90		be := &BenchError{
91			Kind:  ProvisionFailed,
92			Cause: "Nexus refused the request",
93			Check: "kubectl get pods",
94			Err:   errors.New("exec failed: password=hunter2"),
95		}
96		if strings.Contains(be.Error(), "hunter2") {
97			t.Errorf("Error() echoes the wrapped error: %q", be.Error())
98		}
99	}
100	
101	func TestBenchErrorUnwrap(t *testing.T) {
102		sentinel := errors.New("sentinel")
103		with := &BenchError{Kind: Crash, Cause: "c", Check: "k", Err: sentinel}
104		if got := with.Unwrap(); got != sentinel {
105			t.Errorf("Unwrap() = %v, want the wrapped error", got)
106		}
107		if !errors.Is(with, sentinel) {
108			t.Error("errors.Is does not reach the wrapped error")
109		}
110		without := &BenchError{Kind: Crash, Cause: "c", Check: "k"}
111		if got := without.Unwrap(); got != nil {
112			t.Errorf("Unwrap() = %v, want nil when nothing is wrapped", got)
113		}
114		if errors.Is(without, sentinel) {
115			t.Error("errors.Is matched a sentinel that was never wrapped")
116		}
117	}
118	
119	func TestBenchErrorAsThroughWrapping(t *testing.T) {
120		var base error = &BenchError{Kind: Forbidden, Cause: "c", Check: "k"}
121		wrapped := fmt.Errorf("preflight: %w", fmt.Errorf("again: %w", base))
122	
123		var be *BenchError
124		if !errors.As(wrapped, &be) {
125			t.Fatal("errors.As does not find the *BenchError")
126		}
127		if be.Kind != Forbidden {
128			t.Errorf("Kind = %d, want Forbidden (%d)", be.Kind, Forbidden)
129		}
130	}
131	
132	func TestClassifyKubectl(t *testing.T) {
133		tests := []struct {
134			name   string
135			stderr string
136			want   ErrKind
137		}{
138			{
139				name:   "connection refused behind Unable to connect",
140				stderr: "Unable to connect to the server: dial tcp 192.168.1.31:6443: connect: connection refused\n",
141				want:   ClusterUnreachable,
142			},
143			{
144				name:   "TLS handshake timeout behind Unable to connect",
145				stderr: "Unable to connect to the server: net/http: TLS handshake timeout\n",
146				want:   ClusterUnreachable,
147			},
148			{
149				name:   "i/o timeout behind Unable to connect",
150				stderr: "Unable to connect to the server: dial tcp 192.168.1.31:6443: i/o timeout\n",
151				want:   ClusterUnreachable,
152			},
153			{
154				name:   "bare connection refused",
155				stderr: "dial tcp 127.0.0.1:6443: connect: connection refused\n",
156				want:   ClusterUnreachable,
157			},
158			{
159				name:   "forbidden list",
160				stderr: "Error from server (Forbidden): services is forbidden: User \"anthoni\" cannot list resource \"services\" in API group \"\" at the cluster scope\n",
161				want:   Forbidden,
162			},
163			{
164				name:   "forbidden namespace get",
165				stderr: "Error from server (Forbidden): namespaces \"nexus-bench\" is forbidden: User \"anthoni\" cannot get resource \"namespaces\" in API group \"\" in the namespace \"nexus-bench\"\n",
166				want:   Forbidden,
167			},
168			{
169				name:   "Forbidden with a capital and nothing else",
170				stderr: "Error from server (Forbidden): access refused by the gateway\n",
171				want:   Forbidden,
172			},
173			{
174				name:   "NodePort already allocated",
175				stderr: "The Service \"nexus\" is invalid: spec.ports[0].nodePort: Invalid value: 30481: provided port is already allocated\n",
176				want:   NodePortTaken,
177			},
178			{
179				name:   "NodePort out of range",
180				stderr: "The Service \"nexus\" is invalid: spec.ports[0].nodePort: Invalid value: 29999: provided port is not in the valid range. The range of valid ports is 30000-32767\n",
181				want:   NodePortTaken,
182			},
183			{
184				name:   "admission webhook denied",
185				stderr: "Error from server: admission webhook \"validate.kyverno.svc-fail\" denied the request: resource Deployment/nexus-bench/nexus was blocked due to the following policies\n",
186				want:   AdmissionDenied,
187			},
188			{
189				// The more specific reason wins over the generic status.
190				name:   "admission webhook denied reported as Forbidden",
191				stderr: "Error from server (Forbidden): error when creating \"STDIN\": admission webhook \"x\" denied the request: nope\n",
192				want:   AdmissionDenied,
193			},
194		}
195		for _, tt := range tests {
196			t.Run(tt.name, func(t *testing.T) {
197				if got := classifyKubectl(tt.stderr); got != tt.want {
198					t.Errorf("classifyKubectl(%q) = %d, want %d", tt.stderr, got, tt.want)
199				}
200			})
201		}
202	}
203	
204	// An unknown stderr must not be mistaken for any kind of the table, and the
205	// zero value of ErrKind must not stand for "classified": the package needs one
206	// extra value, an "unclassified" kind, that none of the named kinds uses.
207	func TestClassifyKubectlUnknownIsNoNamedKind(t *testing.T) {
208		for _, stderr := range []string{
209			"",
210			"error: unknown command \"frobnicate\" for \"kubectl\"\n",
211			"Error from server (Conflict): Operation cannot be fulfilled on namespaces \"x\": the object has been modified\n",
212		} {
213			t.Run(stderr, func(t *testing.T) {
214				got := classifyKubectl(stderr)
215				for _, k := range namedKinds {
216					if got == k.kind {
217						t.Errorf("classifyKubectl(%q) = %s, but nothing in it says so", stderr, k.name)
218					}
219				}
220			})
221		}
222	}
223

1	package nexusbench
2	
3	import (
4		"context"
5		"errors"
6		"os"
7		"path/filepath"
8		"runtime"
9		"slices"
10		"strings"
11		"testing"
12	)
13	
14	// The tests here never reach a real kubectl: PATH is replaced by a directory
15	// that holds either nothing or a shell script standing in for kubectl, which
16	// records what it was given. They need no cluster, no network and no
17	// requireBench guard.
18	
19	func TestNewExecRunnerKubectlMissing(t *testing.T) {
20		// An empty directory as the whole PATH: no kubectl can be found, whatever
21		// the host has installed.
22		t.Setenv("PATH", t.TempDir())
23	
24		r, err := NewExecRunner("datomir")
25		if err == nil {
26			t.Fatal("NewExecRunner succeeded without kubectl on PATH")
27		}
28		if r != nil {
29			t.Errorf("runner = %v, want nil on error", r)
30		}
31		var be *BenchError
32		if !errors.As(err, &be) {
33			t.Fatalf("error %T is not a *BenchError: %v", err, err)
34		}
35		if be.Kind != KubectlMissing {
36			t.Errorf("Kind = %d, want KubectlMissing (%d)", be.Kind, KubectlMissing)
37		}
38		msg := err.Error()
39		for _, want := range []string{"kubectl", "mise install"} {
40			if !strings.Contains(msg, want) {
41				t.Errorf("message %q does not mention %q", msg, want)
42			}
43		}
44	}
45	
46	// fakeKubectlScript is a stand-in kubectl: it writes its arguments, one per
47	// line, and its standard input to the files named by the environment, answers
48	// on both streams and exits with the requested code.
49	const fakeKubectlScript = `#!/bin/sh
50	printf '%s\n' "$@" > "$KUBECTL_FAKE_ARGS"
51	cat > "$KUBECTL_FAKE_STDIN"
52	echo "stdout-line"
53	echo "stderr-line" >&2
54	exit "${KUBECTL_FAKE_EXIT:-0}"
55	`
56	
57	type fakeKubectlBinary struct {
58		argsFile, stdinFile string
59	}
60	
61	// installFakeKubectl puts the script first on PATH and points it at two files
62	// of the test's temporary directory. The script needs a POSIX shell.
63	func installFakeKubectl(t *testing.T) fakeKubectlBinary {
64		t.Helper()
65		if runtime.GOOS == "windows" {
66			t.Skip("the stand-in kubectl is a POSIX shell script")
67		}
68		bin := t.TempDir()
69		if err := os.WriteFile(filepath.Join(bin, "kubectl"), []byte(fakeKubectlScript), 0o755); err != nil { //nolint:gosec // an executable script is the point
70			t.Fatalf("writing the stand-in kubectl: %v", err)
71		}
72		t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
73	
74		out := t.TempDir()
75		b := fakeKubectlBinary{argsFile: filepath.Join(out, "args"), stdinFile: filepath.Join(out, "stdin")}
76		t.Setenv("KUBECTL_FAKE_ARGS", b.argsFile)
77		t.Setenv("KUBECTL_FAKE_STDIN", b.stdinFile)
78		t.Setenv("KUBECTL_FAKE_EXIT", "0")
79		return b
80	}
81	
82	func (b fakeKubectlBinary) args(t *testing.T) []string {
83		t.Helper()
84		raw, err := os.ReadFile(b.argsFile)
85		if err != nil {
86			t.Fatalf("the stand-in kubectl was not run: %v", err)
87		}
88		return strings.Split(strings.TrimSuffix(string(raw), "\n"), "\n")
89	}
90	
91	func (b fakeKubectlBinary) stdin(t *testing.T) string {
92		t.Helper()
93		raw, err := os.ReadFile(b.stdinFile)
94		if err != nil {
95			t.Fatalf("the stand-in kubectl was not run: %v", err)
96		}
97		return string(raw)
98	}
99	
100	func TestExecRunnerInjectsTheContext(t *testing.T) {
101		tests := []struct {
102			name    string
103			context string
104			args    []string
105			stdin   []byte
106		}{
107			{"read", "datomir", []string{"get", "pods", "-n", "nexus-bench"}, nil},
108			{"apply with a manifest on stdin", "datomir", []string{"apply", "--server-side", "-f", "-"}, []byte("kind: Namespace\n")},
109			{"another context", "k0s-lab", []string{"get", "nodes", "-o", "json"}, nil},
110		}
111		for _, tt := range tests {
112			t.Run(tt.name, func(t *testing.T) {
113				bin := installFakeKubectl(t)
114				r, err := NewExecRunner(tt.context)
115				if err != nil {
116					t.Fatalf("NewExecRunner: %v", err)
117				}
118	
119				stdout, stderr, err := r.Run(context.Background(), tt.stdin, tt.args...)
120				if err != nil {
121					t.Fatalf("Run: %v", err)
122				}
123	
124				want := append([]string{"--context", tt.context}, tt.args...)
125				if got := bin.args(t); !slices.Equal(got, want) {
126					t.Errorf("kubectl got %q, want %q", got, want)
127				}
128				if got := bin.stdin(t); got != string(tt.stdin) {
129					t.Errorf("kubectl stdin = %q, want %q", got, tt.stdin)
130				}
131				if string(stdout) != "stdout-line\n" {
132					t.Errorf("stdout = %q, want %q", stdout, "stdout-line\n")
133				}
134				if string(stderr) != "stderr-line\n" {
135					t.Errorf("stderr = %q, want %q", stderr, "stderr-line\n")
136				}
137			})
138		}
139	}
140	
141	func TestExecRunnerKeepsBothStreamsOnFailure(t *testing.T) {
142		installFakeKubectl(t)
143		t.Setenv("KUBECTL_FAKE_EXIT", "3")
144		r, err := NewExecRunner("datomir")
145		if err != nil {
146			t.Fatalf("NewExecRunner: %v", err)
147		}
148	
149		stdout, stderr, err := r.Run(context.Background(), nil, "get", "pods")
150		if err == nil {
151			t.Fatal("Run succeeded although kubectl exited 3")
152		}
153		if string(stdout) != "stdout-line\n" || string(stderr) != "stderr-line\n" {
154			t.Errorf("streams = %q / %q, want both kept for the classifier", stdout, stderr)
155		}
156	}
157	
158	func TestExecRunnerHonorsACancelledContext(t *testing.T) {
159		installFakeKubectl(t)
160		r, err := NewExecRunner("datomir")
161		if err != nil {
162			t.Fatalf("NewExecRunner: %v", err)
163		}
164		ctx, cancel := context.WithCancel(context.Background())
165		cancel()
166	
167		if _, _, err := r.Run(ctx, nil, "get", "pods"); err == nil {
168			t.Error("Run succeeded on a cancelled context")
169		}
170	}
171

1	package nexusbench
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"slices"
8		"strings"
9		"testing"
10	)
11	
12	// This file holds the scripted kubectl the preflight tests run against, and the
13	// preflight tests. The fake is the contract of the kubectl calls the code under
14	// test may issue; the Deploy and Destroy tests reuse it and extend it.
15	//
16	// The Runner receives the arguments WITHOUT "--context <ctx>": injecting it is
17	// the exec runner's job, and the fake fails the test if a call carries one.
18	// "--request-timeout=<d>" may sit anywhere in the arguments; the fake ignores
19	// it, and "--all-namespaces" is read as "-A".
20	//
21	// Calls the fake answers (anything else fails the test as unscripted):
22	//
23	//	config get-contexts -o name
24	//	get --raw /readyz
25	//	auth can-i <verb> <resource> [-n <ns> | -A]
26	//	get namespace <ns> -o json
27	//	get services -A -o json
28	//	get nodes -o json
