287	// flagsWithValue are the kubectl flags that take their value as the next argument.
288	var flagsWithValue = map[string]bool{
289		"-n": true, "--namespace": true, "-o": true, "--output": true,
290		"--context": true, "-f": true, "-l": true, "--selector": true, "-c": true,
291	}
292	
293	// verbOf returns the kubectl sub-command of args: the first positional argument.
294	// "auth can-i create pods" is therefore "auth", not "create".
295	func verbOf(args []string) string {
296		for i := 0; i < len(args); i++ {
297			switch a := args[i]; {
298			case flagsWithValue[a]:
299				i++
300			case strings.HasPrefix(a, "-"):
301			default:
302				return a
303			}
304		}
305		return ""
306	}
