309		"apply", "create", "delete", "patch", "exec", "label", "annotate", "replace",
310		"edit", "scale", "set", "rollout", "cp", "run", "expose", "taint", "drain",
311		"cordon", "uncordon", "autoscale", "debug", "attach",
312	}
