374	// requiredCheck is a can-i the preflight must ask for an operation.
375	type requiredCheck struct {
376		verb, resource string
377		scope          string // "namespace" (-n <ns>), "cluster" (no -A) or "all" (-A)
378	}
379	
380	// requiredChecks is the list of F2 the plan fixes. The fake answers "yes" to any
381	// other can-i, so the code may ask for more; it may not ask for less.
382	var requiredChecks = map[Op][]requiredCheck{
383		OpUp: {
384			{"create", "namespaces", "cluster"},
385			{"create", "persistentvolumeclaims", "namespace"},
386			{"create", "services", "namespace"},
387			{"create", "deployments", "namespace"},
388			{"create", "secrets", "namespace"},
389			{"create", "pods/exec", "namespace"},
390			{"list", "services", "all"},
391		},
392		OpProvision: {{"create", "pods/exec", "namespace"}},
393		OpDown:      {{"delete", "namespaces", "cluster"}},
394	}
395	
396	func (c requiredCheck) matches(q canIQuery, p Params) bool {
397		if q.verb != c.verb || q.resource != c.resource {
398			return false
399		}
400		switch c.scope {
401		case "namespace":
402			return q.namespace == p.Namespace && !q.allNamespaces
403		case "all":
404			return q.allNamespaces
405		default:
406			return !q.allNamespaces
407		}
408	}
