139	// Run implements Runner.
140	func (f *fakeKubectl) Run(_ context.Context, stdin []byte, args ...string) (stdout, stderr []byte, err error) {
141		f.calls = append(f.calls, fakeCall{args: slices.Clone(args), stdin: slices.Clone(stdin)})
142		if slices.Contains(args, "--context") {
143			f.t.Errorf("kubectl call %q passes --context itself: the runner injects it", args)
144		}
145		if verb := verbOf(args); isWriteVerb(verb) {
146			return nil, []byte("the fake refuses a write: " + verb), errFakeExit1
147		}
148	
149		norm := normalizeArgs(args)
150		switch joined := strings.Join(norm, " "); {
151		case joined == "config get-contexts -o name":
152			return []byte(f.contexts), nil, nil
153		case joined == "get --raw /readyz":
154			return f.readyz.reply()
155		case strings.HasPrefix(joined, "auth can-i "):
156			return f.answerCanI(norm[2:])
157		case joined == "get namespace "+f.p.Namespace+" -o json":
158			return f.answerNamespace()
159		case joined == "get services -A -o json":
160			return f.answerServices()
161		case joined == "get nodes -o json":
162			return f.answerNodes()
163		default:
164			f.t.Errorf("unscripted kubectl call: %q", args)
165			return nil, []byte("unscripted call"), errFakeExit1
166		}
167	}
168	
169	func (r fakeReply) reply() ([]byte, []byte, error) {
170		return []byte(r.stdout), []byte(r.stderr), r.err
171	}
172	
173	func (f *fakeKubectl) answerCanI(args []string) ([]byte, []byte, error) {
174		var q canIQuery
175		var positional []string
176		for i := 0; i < len(args); i++ {
177			switch args[i] {
178			case "-n":
179				if i+1 < len(args) {
180					i++
181					q.namespace = args[i]
182				}
183			case "-A":
184				q.allNamespaces = true
185			default:
186				positional = append(positional, args[i])
187			}
188		}
189		if len(positional) != 2 {
190			f.t.Errorf("auth can-i wants a verb and a resource, got %q", args)
191			return nil, []byte("bad can-i"), errFakeExit1
192		}
193		q.verb, q.resource = positional[0], positional[1]
194		if q.namespace != "" && q.namespace != f.p.Namespace {
195			f.t.Errorf("auth can-i %q asks about namespace %q, the run is about %q", args, q.namespace, f.p.Namespace)
196		}
197		f.asked = append(f.asked, q)
198		if f.denied[q.String()] {
199			return []byte("no\n"), nil, errFakeExit1
200		}
201		return []byte("yes\n"), nil, nil
202	}
