204	func (f *fakeKubectl) answerNamespace() ([]byte, []byte, error) {
205		if f.nsReply != nil {
206			return f.nsReply.reply()
207		}
208		if !f.nsPresent {
209			return nil, []byte("Error from server (NotFound): namespaces \"" + f.p.Namespace + "\" not found\n"), errFakeExit1
210		}
211		meta := map[string]any{"name": f.p.Namespace, "uid": "6b1f0f8e-0000-4000-8000-000000000001"}
212		if f.nsLabels != nil {
213			meta["labels"] = f.nsLabels
214		}
215		return f.mustJSON(map[string]any{
216			"apiVersion": "v1",
217			"kind":       "Namespace",
218			"metadata":   meta,
219			"status":     map[string]any{"phase": "Active"},
220		}), nil, nil
221	}
222	
223	func (f *fakeKubectl) answerServices() ([]byte, []byte, error) {
224		if f.servicesReply != nil {
225			return f.servicesReply.reply()
226		}
227		items := make([]any, 0, len(f.services))
228		for _, s := range f.services {
229			ports := make([]any, 0, len(s.nodePorts))
230			for i, np := range s.nodePorts {
231				ports = append(ports, map[string]any{"name": "p" + string(rune('0'+i)), "port": 80 + i, "targetPort": 8080 + i, "protocol": "TCP", "nodePort": np})
232			}
233			if len(ports) == 0 {
234				ports = append(ports, map[string]any{"port": 443, "protocol": "TCP", "targetPort": 6443})
235			}
236			kind := "ClusterIP"
237			if len(s.nodePorts) > 0 {
238				kind = "NodePort"
239			}
240			items = append(items, map[string]any{
241				"metadata": map[string]any{"name": s.name, "namespace": s.namespace},
242				"spec":     map[string]any{"type": kind, "ports": ports},
243			})
244		}
245		return f.mustJSON(map[string]any{"apiVersion": "v1", "kind": "List", "items": items}), nil, nil
246	}
