248	func (f *fakeKubectl) answerNodes() ([]byte, []byte, error) {
249		addresses := make([]any, 0, len(f.nodeAddresses))
250		for _, a := range f.nodeAddresses {
251			addresses = append(addresses, map[string]any{"type": a[0], "address": a[1]})
252		}
253		return f.mustJSON(map[string]any{
