263	func (f *fakeKubectl) mustJSON(v any) []byte {
264		f.t.Helper()
265		raw, err := json.Marshal(v)
266		if err != nil {
267			f.t.Fatalf("encoding a fake answer: %v", err)
268		}
269		return raw
