272	// normalizeArgs drops the request timeout and spells --all-namespaces as -A.
273	func normalizeArgs(args []string) []string {
274		out := make([]string, 0, len(args))
275		for _, a := range args {
276			switch {
277			case strings.HasPrefix(a, "--request-timeout"):
278			case a == "--all-namespaces":
279				out = append(out, "-A")
280			default:
281				out = append(out, a)
282			}
283		}
284		return out
285	}
