308	var writeVerbs = []string{
309		"apply", "create", "delete", "patch", "exec", "label", "annotate", "replace",
310		"edit", "scale", "set", "rollout", "cp", "run", "expose", "taint", "drain",
311		"cordon", "uncordon", "autoscale", "debug", "attach",
312	}
313	
314	func isWriteVerb(verb string) bool { return slices.Contains(writeVerbs, verb) }
315	
316	// recordedWrites lists the calls the fake saw whose sub-command writes.
317	func (f *fakeKubectl) recordedWrites() []string {
318		var out []string
319		for _, c := range f.calls {
320			if isWriteVerb(verbOf(c.args)) {
321				out = append(out, strings.Join(c.args, " "))
322			}
323		}
324		return out
325	}
