348	// requireCleanError checks what every failure of the bench promises: a
349	// *BenchError with a cause and a check, no password and no raw sub-process text.
350	func requireCleanError(t *testing.T, err error) *BenchError {
351		t.Helper()
352		var be *BenchError
353		if !errors.As(err, &be) {
354			t.Fatalf("error %T is not a *BenchError: %v", err, err)
355		}
356		if be.Cause == "" {
357			t.Error("the error has no Cause")
358		}
359		if !strings.Contains(be.Check, "kubectl") && !strings.Contains(be.Check, "mise") {
360			t.Errorf("Check %q names neither a kubectl command nor a mise task", be.Check)
361		}
362		msg := strings.ToLower(err.Error())
363		for _, banned := range []string{"password", fakeSecret} {
364			if strings.Contains(msg, banned) {
365				t.Errorf("message %q contains %q", err.Error(), banned)
366			}
367		}
368		return be
369	}
