380	// requiredChecks is the list of F2 the plan fixes. The fake answers "yes" to any
381	// other can-i, so the code may ask for more; it may not ask for less.
382	var requiredChecks = map[Op][]requiredCheck{
383		OpUp: {
384			{"create", "namespaces", "cluster"},
385			{"create", "persistentvolumeclaims", "namespace"},
386			{"create", "services", "namespace"},
387			{"create", "deployments", "namespace"},
388			{"create", "secrets", "namespace"},
389			{"create", "pods/exec", "namespace"},
390			{"list", "services", "all"},
391		},
392		OpProvision: {{"create", "pods/exec", "namespace"}},
393		OpDown:      {{"delete", "namespaces", "cluster"}},
394	}
