616				onlyCalls: []string{"config get-contexts -o name"},
617			},
618			{
619				name: "API server refuses the connection",
620				op:   OpUp,
621				setup: func(f *fakeKubectl) {
622					f.readyz = fakeReply{
623						stderr: "Unable to connect to the server: dial tcp 192.168.1.31:6443: connect: connection refused\n",
624						err:    errFakeExit1,
625					}
626				},
627				kind:      ClusterUnreachable,
628				onlyCalls: []string{"config get-contexts -o name", "get --raw /readyz"},
629			},
630			{
631				name: "API server times out",
632				op:   OpStatus,
633				setup: func(f *fakeKubectl) {
