642			{
643				name: "unreachable cluster whose stderr carries a secret",
644				op:   OpUp,
645				setup: func(f *fakeKubectl) {
646					f.readyz = fakeReply{
647						stderr: "Unable to connect to the server: proxyconnect tcp: dial tcp user:password=" + fakeSecret + "@proxy:3128: connection refused\n",
648						err:    errFakeExit1,
649					}
650				},
651				kind: ClusterUnreachable,
652			},
653			{
654				name: "namespace of ours is not ours: no labels at all but the API server's",
655				op:   OpUp, setup: foreignNamespace(unlabeled),
656				kind: NamespaceForeign, mention: []string{"nexus-bench"},
657			},
658			{
659				name: "down refuses a namespace without our label",
660				op:   OpDown, setup: foreignNamespace(unlabeled),
661				kind: NamespaceForeign, mention: []string{"nexus-bench"},
662			},
