729				op:   OpUp,
730				setup: func(f *fakeKubectl) {
731					f.nsReply = &fakeReply{
732						stderr: "Error from server (Forbidden): namespaces \"nexus-bench\" is forbidden: User \"anthoni\" cannot get resource \"namespaces\" in API group \"\" in the namespace \"nexus-bench\"\n",
733						err:    errFakeExit1,
734					}
735				},
736				kind: Forbidden,
737			},
738			{
739				name: "get services is forbidden although can-i said yes",
740				op:   OpUp,
741				setup: func(f *fakeKubectl) {
742					f.servicesReply = &fakeReply{
743						stderr: "Error from server (Forbidden): services is forbidden: User \"anthoni\" cannot list resource \"services\" in API group \"\" at the cluster scope\n",
744						err:    errFakeExit1,
745					}
746				},
747				kind: Forbidden,
748			},
749			{
750				name: "get namespace fails in a way nobody planned, and the stderr holds a secret",
751				op:   OpUp,
752				setup: func(f *fakeKubectl) {
753					f.nsReply = &fakeReply{
754						stderr: "Error from server (InternalError): Internal error occurred: token=" + fakeSecret + " rejected\n",
755						err:    errFakeExit1,
756					}
757				},
758				unplanned: true,
759			},
760		}
761		// Every verb and resource of the required list, denied one at a time.
762		for _, op := range []Op{OpUp, OpProvision, OpDown} {
763			for _, c := range requiredChecks[op] {
764				cases = append(cases, failCase{
765					name: "can-i says no to " + c.verb + " " + c.resource + " (" + testOpName[op] + ")",
766					op:   op,
767					setup: func(f *fakeKubectl) {
768						// The namespace is there for provision and down, so that the
769						// order of the checks does not matter to the outcome.
770						if op != OpUp {
771							f.ours()
772						}
773						f.deny(c.verb, c.resource)
774					},
775					kind:    Forbidden,
776					mention: []string{c.verb, c.resource},
777				})
778			}
779		}
780		return cases
781	}
