39	const (
40		// Defaults of D-B and D-C. The NodePorts were free on 2026-11-16; the block
41		// 30483-30489 stays reserved for the next NX stories.
42		defaultContext        = "datomir"
43		defaultNamespace      = "nexus-bench"
44		defaultHTTPNodePort   = 30481
45		defaultDockerNodePort = 30482
46		defaultImage          = "docker.io/sonatype/nexus3"
47		defaultImageTag       = "3.98.1"
48		defaultJVMOpts        = "-Xms1g -Xmx1g -XX:MaxDirectMemorySize=1g -Djava.util.prefs.userRoot=/nexus-data/javaprefs"
49	
50		nodePortMin = 30000
51		nodePortMax = 32767
52	
53		// zotRegistry is the registry the Kyverno policy verify-tvp-images guards:
54		// an image from it must be signed, and the bench image is not.
55		zotRegistry = "tvp-zot.incus:5000"
56	
57		maxJVMOptsLen   = 512
58		maxImageLen     = 255
59		maxHostLen      = 253
60		maxPathLen      = 4096
61		maxContextLen   = 253 // a kubeconfig context name is bounded like a DNS name
62		maxNamespaceLen = 63  // a DNS-1123 label
